"use strict";
const handsetLives={silver:{title:'下雨以前的那首歌',date:'2004 / 09 / 12',friend:'老杜',owner:'阿禾',sms:[['老杜','琴房窗户漏雨，别把贝斯靠窗放。下午两点，我先过去拿钥匙。'],['妈','饭在锅里，热一下再吃。今天别为了赶车不吃饭。'],['小夏','昨晚台下那个人是我姐。她说你们最后一首好听，问叫什么。'],['10086','本月短信套餐余量提醒。本机保存的年代模拟信息，不产生费用。']],qq:[['intro','昨晚那首歌，还没有名字。',['老杜：先叫《下雨以前》吧，就录音带上那个名字。','我把现场的掌声也留了，没剪。那是我们第一次有人喊再来一首。']],['cable','坏掉的线还修得好吗？',['老杜：是插头松了，不是贝斯坏了。老许收了两块钱。','演出前你一直以为自己弹错，其实是线断断续续。']],['finish','把原来的掌声留着，下周再排一次。',['老杜：好，谁也别删。星期六还是两点。','小夏说要替我们画一张像样的海报。现在那张手写的，你也留着。']]],webTitle:'北门琴房 / 排练留言板',web:'9月11日，周六。场地押金退回20元。下午两点排练，晚上九点半上台。末班车23:00。老杜在纸边补了一句：十点半提醒阿禾收线。<hr>9月12日补记：下次排练改为9月18日14:00，旧海报日期作废。现场带的最后四十秒是掌声，备份时不要当空白剪掉。',album:'演出海报背面的排练时间，与琴房留言不是同一天。海报是上周印的，改期写在手机网页里。'},white:{title:'第十二张合照',date:'2010 / 06 / 06',friend:'同桌',owner:'林恬',sms:[['同桌','我把十一张先传给你。第十二张没糊，你别删，那张有你自己。'],['外婆','照片洗好了给我留一张大的，我眼睛不太看得清。'],['班长','周一毕业照补拍，九点教学楼前。带校服，不是今天。'],['照相馆','照片待取，取件号0612。周日17:30前营业。店内剧情信息，不是真实商家。']],qq:[['intro','你为什么非要留下第十二张？',['同桌：前面十一张你都站在相机后面。','那张是小周按的快门，你刚跑过去，头发都没理好。可大家都在笑。']],['print','给外婆那张，要洗多大？',['同桌：七寸吧。别用聊天里压过的图，原文件在卡里。','取件号0612不是六月十二号，是店里的流水号。别等到下周才去。']],['finish','第十二张也留下，七寸那张给外婆。',['同桌：这就对了。明天补拍不用你再当摄影师。','你总说十年以后再看。先给今年的自己留一张吧。']]],webTitle:'六月相册 / 洗印便笺',web:'6月6日，周日。照相馆17:30关门，取件号0612。原文件4000×3000，给外婆洗七寸，不用QQ相册里压缩过的版本。<hr>6月7日，周一。九点教学楼前补拍。天气预报说有太阳，记得带校服。不是取照片的日子。',album:'第十二张没有删。照片背面写着：别总躲到相机后面。'}};
// Fictional records belong to each handset, never to ordinary mode.
handsetLives.silver.qq.splice(2,0,['archive','论坛里那个“空白尾巴”是什么意思？',['老杜：录音末尾那四十秒不是没录上。那天台下只有七个人，喊得像七十个。','小夏把帖子里的排练日改过了。别照着旧海报上的日期白跑一趟。'],['forum']]);
handsetLives.white.qq.splice(2,0,['archive','洗印帖下面为什么有人提醒别发原图？',['同桌：给照相馆用原图，发论坛用缩图就好。','第十二张背后有校牌，别把大家的名字一起传出去。外婆那张也不用放网上。'],['forum']]);
const lifeForums={silver:{title:'北门BBS / 空白尾巴',rows:[['小夏','09-12 11:42','手写海报是上周定的。老板临时把周六琴房借出去，下次排练挪到9月18日，还是下午两点。已经改到琴房留言里了。'],['D调','09-12 12:06','那段录音到最后突然变响，我以为磁带坏了。'],['老杜','09-12 12:14','没坏，是我们第一次有人喊再来一首。谁把尾巴剪了，我跟谁急。'],['小夏','09-12 12:21','照片背面有一块墨水糊了，原来的名字我还认得。等阿禾把手机拿回去再问他。']]},white:{title:'六月BBS / 十二张照片',rows:[['照相馆小许','06-06 12:30','大照片请送存储卡里的原文件，QQ传来的小图放大后会糊。今天17:30关门。'],['匿名同学','06-06 13:08','0612是你们下周六来取吗？'],['同桌','06-06 13:15','不是日期，是流水号。今天就能拿。补拍才是周一。'],['小周','06-06 13:27','最后一张我按的，林恬总算也在照片里了。发论坛前把校牌遮一下，给外婆的那张留原样。']]}};
nightShop.handsetStories={silver:{read:[],talk:[]},white:{read:[],talk:[]}};
try{const raw=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop?.handsetStories;for(const id of ['silver','white']){nightShop.handsetStories[id].read=['sms','photo','browser','forum'].filter(k=>raw?.[id]?.read?.includes(k));nightShop.handsetStories[id].talk=['intro','cable','print','archive','finish'].filter(k=>handsetLives[id].qq.some(q=>q[0]===k)&&raw?.[id]?.talk?.includes(k));}}catch{}
function handsetLifeRead(kind){if(!handsetLives[tide.device]||!['sms','photo','browser','forum'].includes(kind))return false;const s=nightShop.handsetStories[tide.device];if(!s.read.includes(kind)){s.read.push(kind);tideSave();}return true;}
function handsetLifeTalk(id){const c=handsetLives[tide.device],s=nightShop.handsetStories[tide.device];if(!c||!c.qq.some(q=>q[0]===id)||s.talk.includes(id))return false;if(id!=='intro'&&!s.talk.includes('intro'))return false;const q=c.qq.find(q=>q[0]===id);if(q[3]?.some(k=>!s.read.includes(k)))return false;if(id==='finish'&&(!s.read.includes('photo')||!s.read.includes('browser')||s.talk.length<2))return false;s.talk.push(id);tideSave();return true;}
const lifeSmsBase=tideSms;
tideSms=function(){const c=handsetLives[tide.device];if(!c)return lifeSmsBase();handsetLifeRead('sms');const m=/^life:sms:(\d)$/.exec(tideView);if(m){const row=c.sms[+m[1]];if(!row)return tideFrame('信息','<p>这条记录不存在。</p>');return tideFrame(row[0],`<article class="deep-chat"><small>${c.date} / 本机保存</small><p>${escapeHTML(row[1])}</p></article><button data-life-view="sms">返回收件箱</button>`);}return tideFrame(`信息 / ${c.owner}`,`<small>${c.title} · 此机独立记录</small><div class="tide-list">${c.sms.map(([n,t],i)=>`<button data-life-view="life:sms:${i}"><b>${n}</b><span>${t.slice(0,20)}…</span></button>`).join('')}</div>`);};
const lifeQQBase=tideQQ;
tideQQ=function(){const c=handsetLives[tide.device];if(!c)return lifeQQBase();const s=nightShop.handsetStories[tide.device],rows=[];for(const id of s.talk){const q=c.qq.find(q=>q[0]===id);rows.push(['我',q[1],c.date]);q[2].forEach(t=>rows.push([c.friend,t.replace(/^[^：]+：/,''),'本机记录']));}return tideFrame(`QQ / ${c.friend}`,`<small>${c.title}</small><div class="deep-chat">${rows.length?deepBubbles(rows):'<p>对方的头像亮着。这部手机里的往来，与其他手机无关。</p>'}</div><nav class="deep-choices">${c.qq.filter(q=>!s.talk.includes(q[0])&&(!q[3]||q[3].every(k=>s.read.includes(k)))&&(q[0]==='intro'||s.talk.includes('intro'))&&(q[0]!=='finish'||s.read.includes('photo')&&s.read.includes('browser')&&s.talk.length>=2)).map(q=>`<button data-life-talk="${q[0]}">${q[1]}</button>`).join('')}</nav>`);};
const lifeAlbumBase=tideAlbum;
tideAlbum=function(){const c=handsetLives[tide.device];if(!c)return lifeAlbumBase();handsetLifeRead('photo');return lifeAlbumBase()+`<details class="life-album-note"><summary>相册里夹着的便笺</summary><p>${c.album}</p></details>`;};
const lifeBrowserBase=tideBrowser;
tideBrowser=function(){const c=handsetLives[tide.device];if(!c)return lifeBrowserBase();if(tideView==='life:web'){handsetLifeRead('browser');return tideFrame(c.webTitle,`<article class="tide-web"><h3>${c.webTitle}</h3><small>${c.date} / 本机网页缓存</small><p>${c.web}</p></article><button data-life-view="browser">返回浏览记录</button>`);}return tideFrame(`浏览器 / ${c.owner}`,`<div class="tide-list"><button data-life-view="life:web">${c.webTitle}</button><button data-life-view="life:forum">${lifeForums[tide.device].title}</button><button data-life-view="life:weather">${tide.device==='silver'?'周六 / 雨后的天气':'周一 / 补拍前的天气'}</button></div>${tideView==='life:weather'?'<p>旧天气预报缓存：明日转晴。日期以当时缓存为准。</p>':''}`);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-life-view],[data-life-talk]');if(!b)return;e.preventDefault();if(b.dataset.lifeTalk){handsetLifeTalk(b.dataset.lifeTalk);return refreshPhone();}tideView=b.dataset.lifeView;if(tideView==='sms'||tideView.startsWith('life:sms'))phoneState.app='sms';if(['browser','life:web','life:weather','life:forum'].includes(tideView))phoneState.app='browser';refreshPhone();});

try{const saved=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop?.handsetStories;for(const id of ['silver','white'])nightShop.handsetStories[id].returned=saved?.[id]?.returned===true;}catch{}
let lifeReplyNotice='';
function handsetLifeReturn(owner,detail,reason){const id=tide.device,c=handsetLives[id],s=nightShop.handsetStories[id];if(!c||!s||!['sms','photo','browser','forum'].every(k=>s.read.includes(k))||!s.talk.includes('archive'))return false;const valid=id==='silver'?owner==='阿禾'&&detail==='0918'&&reason==='applause':owner==='林恬'&&detail==='0612'&&reason==='original';if(!valid){lifeReplyNotice='你把几条记录放在一起，仍有一处对不上。留言先留在草稿里。';return false;}if(s.returned)return true;s.returned=true;lifeReplyNotice='留言已记下。';tideSave();return true;}
const lifeForumBrowserBase=tideBrowser;
tideBrowser=function(){const f=lifeForums[tide.device];if(!f||tideView!=='life:forum')return lifeForumBrowserBase();handsetLifeRead('forum');return tideFrame(f.title,`<div class="life-forum"><small>本机缓存 / 原创剧情论坛</small>${f.rows.map(([name,time,text],i)=>`<article><header>${i+1}楼 · ${escapeHTML(name)} <time>${time}</time></header><p>${escapeHTML(text)}</p></article>`).join('')}</div><button data-life-view="browser">返回浏览记录</button>`);};
const lifeReturnQQBase=tideQQ;
tideQQ=function(){const c=handsetLives[tide.device];if(!c)return lifeReturnQQBase();const s=nightShop.handsetStories[tide.device];if(tideView==='life:reply')return tideFrame('留给失主的一句话',s.returned?`<article class="life-return"><h3>手机里多了一条回信</h3><p>${tide.device==='silver'?'阿禾：谢谢。别人听见的是那首歌，我听见的是后面那四十秒。手机我周六来拿，带一盘空白带给你。':'林恬：照片拿到了。外婆看了好久，最后只问了一句：这次你也在里面了，对吧？谢谢你没有把原图发到论坛。'}</p><small>这部手机的回访已完成；仍可继续翻记录和游玩。</small></article><button data-life-view="qq">回到聊天</button>`:`<form class="life-reply" data-life-reply><p>手机店准备给失主留一张纸条。你记得这些记录里的人和事吗？</p><label>这部手机属于谁<input name="owner" maxlength="12" autocomplete="off" required></label><label>${tide.device==='silver'?'下一次排练日期（月日四位）':'照相馆的取件号'}<input name="detail" inputmode="numeric" maxlength="4" required></label><label>你会替他保留什么？<select name="reason"><option value="">先想一想</option><option value="applause">录音最后的掌声</option><option value="original">给家人的原始照片</option><option value="delete">清空所有旧记录</option></select></label><button>把纸条夹回手机袋</button>${lifeReplyNotice?`<p role="status">${lifeReplyNotice}</p>`:''}</form><button data-life-view="qq">先不写，再看看</button>`);return lifeReturnQQBase()+(['sms','photo','browser','forum'].every(k=>s.read.includes(k))&&s.talk.includes('archive')?`<div class="life-return-entry"><button data-life-view="life:reply">${s.returned?'翻看回信':'给失主留张纸条'}</button></div>`:'');};
document.addEventListener('submit',e=>{if(!e.target.matches('[data-life-reply]'))return;e.preventDefault();const f=new FormData(e.target);handsetLifeReturn(String(f.get('owner')||'').trim(),String(f.get('detail')||'').trim(),String(f.get('reason')||''));refreshPhone();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-life-view]');if(!b)return;if(['qq','life:reply'].includes(b.dataset.lifeView)){phoneState.app='qq';tideView=b.dataset.lifeView;lifeReplyNotice='';refreshPhone();}});
const lifeForumAppBase=tideForum;
tideForum=function(){const f=lifeForums[tide.device];if(!f)return lifeForumAppBase();handsetLifeRead('forum');return tideFrame(f.title,`<div class="life-forum"><small>本机缓存 / 原创剧情论坛</small>${f.rows.map(([name,time,text],i)=>`<article><header>${i+1}楼 · ${escapeHTML(name)} <time>${time}</time></header><p>${escapeHTML(text)}</p></article>`).join('')}</div>`);};
